#!/bin/sh
set -eu

base_url=${BAKE_RELEASE_BASE_URL:-https://bake.justar.dev}
install_root=${BAKE_INSTALL_ROOT:-"$HOME/.local/share/bake"}
bin_dir=${BAKE_BIN_DIR:-"$HOME/.local/bin"}

command -v curl >/dev/null 2>&1 || { echo 'Bake install needs curl.' >&2; exit 1; }
command -v tar >/dev/null 2>&1 || { echo 'Bake install needs tar.' >&2; exit 1; }
command -v node >/dev/null 2>&1 || { echo 'Bake install needs Node.js 24 or newer.' >&2; exit 1; }
node -e 'process.exit(Number(process.versions.node.split(".")[0]) >= 24 ? 0 : 1)' || {
  echo 'Bake install needs Node.js 24 or newer.' >&2
  exit 1
}

case "$(uname -s)-$(uname -m)" in
  Darwin-arm64) target=darwin-arm64 ;;
  Darwin-x86_64) target=darwin-x64 ;;
  Linux-aarch64|Linux-arm64) target=linux-arm64 ;;
  Linux-x86_64) target=linux-x64 ;;
  *) echo 'This platform has no Bake release archive.' >&2; exit 1 ;;
esac

temporary=$(mktemp -d "${TMPDIR:-/tmp}/bake-install.XXXXXX")
animation_pid=
# Append one progress event, its fields separated by tabs; see installer-animation.ts.
report() {
  [ -n "$animation_pid" ] || return 0
  (IFS=$(printf '\t'); printf '%s\n' "$*") >> "$temporary/progress"
}
stop_animation() {
  if [ -n "$animation_pid" ]; then
    report "$@"
    wait "$animation_pid" 2>/dev/null || :
    animation_pid=
  fi
}
cleanup() {
  stop_animation stop
  if [ -f "$temporary/errors" ]; then cat "$temporary/errors" >&2; fi
  rm -rf "$temporary"
}
trap cleanup EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
if [ -t 2 ] && [ "${TERM:-}" != dumb ] && [ -z "${CI:-}" ] && [ "${BAKE_NO_ANIMATION:-}" != 1 ]; then
  cat > "$temporary/animation.cjs" <<'ANIMATION'
// Generated by bun scripts/release/embed-animation.ts.
// # BEGIN ANIMATION
var D=require("node:fs"),oe=require("node:path");var E={reference:"#60a5fa",code:"#c4b5fd",running:"#f97316",compacting:"#3b82f6",done:"#22c55e",failed:"#ef4444",asking:"#0ea5e9",waiting:"#eab308",output:"#b4b8bf"},p={from:E.running,to:"#fbbf24",glint:"#fff7ed",track:"#44403c"};var W=80,S=2,K=2,le=10,ce=32,L=1600,k=4,j=1800,N=[[0,0],[1,0],[2,0],[3,0],[3,1],[3,2],[3,3],[2,3],[1,3],[0,3],[0,2],[0,1]],de=4,ue=[[1,2,4,64],[8,16,32,128]],H=["-","\\","|","/"],P={unicode:{fill:"\u2501",edge:"\u2578",track:"\u2500",done:"\u2713",failed:"\u2717",separator:" \u00b7 ",ellipsis:"\u2026"},ascii:{fill:"=",edge:">",track:"-",done:"+",failed:"x",separator:" - ",ellipsis:"..."}},F=(e)=>Math.min(1,Math.max(0,Number.isFinite(e)?e:0));function _(e,t,s){let n=F(s),r=(l,i)=>Number.parseInt(l.slice(1+i*2,3+i*2),16);return`#${[0,1,2].map((l)=>Math.round(r(e,l)+(r(t,l)-r(e,l))*n).toString(16).padStart(2,"0")).join("")}`}function fe(e,t){let s=Math.floor(Math.max(0,e)/W);if(t==="ascii")return[{text:`${H[s%H.length]} `,color:p.from,bold:!0}];let n=[0,0],r=s%N.length;for(let i=0;i<de;i++){let[o,a]=N[(r-i+N.length)%N.length];n[o>>1]|=ue[o&1][a]}let l=N[r][0]>>1;return n.map((i,o)=>({text:String.fromCodePoint(10240+i),color:o===l?p.to:p.from,bold:!0}))}function pe(e,t,s,n){let r=Math.max(0,Math.floor(s)),{fill:l,edge:i,track:o}=P[n],a=[],c=Math.max(0,e),f=(u)=>_(p.from,p.to,r<=1?0:u/(r-1));if(t!==void 0){let u=F(t)*r,m=Math.floor(u),y=m<r&&u-m>=0.5,ie=c%L/L*(m+k*2)-k;for(let x=0;x<m;x++){let ae=Math.max(0,1-Math.abs(x-ie)/k)**2*0.75;a.push({text:l,color:_(f(x),p.glint,ae)})}if(y){let x=(1-Math.cos(2*Math.PI*(c%L)/L))/2;a.push({text:i,color:_(f(m),p.glint,0.2+0.5*x)})}for(let x=m+(y?1:0);x<r;x++)a.push({text:o,dim:!0});return v(a)}let h=c%j/j,g=h<0.5,R=(1-Math.cos(Math.PI*(g?h*2:(1-h)*2)))/2*Math.max(0,r-1),d=Math.max(3,Math.round(r/4));for(let u=0;u<r;u++){let m=g?R-u:u-R,y=m<-0.5||m>d?0:m<=0?1:(1-m/d)**1.5;if(y<0.15){a.push({text:o,dim:!0});continue}a.push({text:n==="ascii"&&y<0.35?o:l,color:y>