=void 0||e.TERM===""||e.TERM==="dumb")return"ascii";return"unicode"}function V(e){if(e.NO_COLOR!==void 0)return"none";let t=e.COLORTERM?.toLowerCase();if(t==="truecolor"||t==="24bit"||e.WT_SESSION!==void 0&&e.WT_SESSION!=="")return"truecolor";return"ansi256"}function me(e){let t=[0,95,135,175,215,255],s=(i)=>t.reduce((o,a,c)=>Math.abs(a-i)<Math.abs(t[o]-i)?c:o,0),[n,r,l]=[1,3,5].map((i)=>s(Number.parseInt(e.slice(i,i+2),16)));return 16+36*n+6*r+l}function Z(e,t){if(t==="none")return e.map((n)=>n.text).join("");let s=[];for(let n of e){let r=[...n.bold===!0?["1"]:[],...n.dim===!0?["2"]:[]];if(n.color!==void 0){let o=(a)=>Number.parseInt(n.color.slice(1+a*2,3+a*2),16);r.push(t==="truecolor"?`38;2;${o(0)};${o(1)};${o(2)}`:`38;5;${me(n.color)}`)}let l=r.join(";"),i=s.at(-1);if(i!==void 0&&i.code===l)i.text+=n.text;else s.push({code:l,text:n.text})}return s.map((n)=>n.code===""?n.text:`\x1B[${n.code}m${n.text}\x1B[0m`).join("")}function v(e){let t=[];for(let s of e){let n=t.at(-1);if(n!==void 0&&n.color===s.color&&n.dim===s.dim&&n.bold===s.bold)t[t.length-1]={...n,text:n.text+s.text};else t.push(s)}return t}function w(e){return[...e].length}function M(e,t){return t==="unicode"?e:e.replace(/\u2192/gu,"->").replace(/\u00b7/gu,"-").replace(/\u2026/gu,"...")}function I(e,t,s){let n=Math.max(0,Math.floor(t));if(e.reduce((a,c)=>a+w(c.text),0)<=n)return e;let r=P[s].ellipsis,l=Math.max(0,n-w(r)),i=[],o=0;for(let a of e){let c=[...a.text];if(o+c.length<=l){i.push(a),o+=c.length;continue}let f=c.slice(0,l-o).join("");return i.push({...a,text:`${f}${n>=w(r)?r:""}`}),i}return i}var ee=18,te="  ";function ne(e,t,s){let n=e.isTTY===!0&&t.TERM!=="dumb"&&!t.CI&&t.BAKE_NO_ANIMATION!=="1",r=V(t),l=Q(t),i=Date.now(),o,a=!n,c=()=>(e.columns!==void 0&&e.columns>0?e.columns:80)-1-te.length,f=(d)=>`${te}${Z(d,r)}`,h=()=>{if(o===void 0)return;let d=Date.now();e.write(`\r\x1B[2K${f(z({label:o.label,...o.fraction===void 0?{}:{fraction:o.fraction},...o.detail===void 0?{}:{detail:o.detail}},{time: